	//   "FRIED"
	//   "PAN_FRIED"
	//   "STIR_FRIED"
	//   "SAUTEED"
	//   "ROASTED"
	//   "BARBECUED"
	//   "SEARED"
	//   "SMOKED"
	//   "FERMENTED"
