func (s *PerDocData) UnmarshalJSON(data []byte) error {
	type NoMethod PerDocData
	var s1 struct {
		WhirlpoolDiscount           gensupport.JSONFloat64 `json:"WhirlpoolDiscount"`
		BodyWordsToTokensRatioBegin gensupport.JSONFloat64 `json:"bodyWordsToTokensRatioBegin"`
		BodyWordsToTokensRatioTotal gensupport.JSONFloat64 `json:"bodyWordsToTokensRatioTotal"`
		CommercialScore             gensupport.JSONFloat64 `json:"commercialScore"`
		Pagerank                    gensupport.JSONFloat64 `json:"pagerank"`
		Pagerank0                   gensupport.JSONFloat64 `json:"pagerank0"`
		Pagerank1                   gensupport.JSONFloat64 `json:"pagerank1"`
		Pagerank2                   gensupport.JSONFloat64 `json:"pagerank2"`
		SpambrainTotalDocSpamScore  gensupport.JSONFloat64 `json:"spambrainTotalDocSpamScore"`
		SpamtokensContentScore      gensupport.JSONFloat64 `json:"spamtokensContentScore"`
		TopPetacatWeight            gensupport.JSONFloat64 `json:"topPetacatWeight"`
		*NoMethod
	}
	s1.NoMethod = (*NoMethod)(s)
	if err := json.Unmarshal(data, &s1); err != nil {
		return err
	}
	s.WhirlpoolDiscount = float64(s1.WhirlpoolDiscount)
	s.BodyWordsToTokensRatioBegin = float64(s1.BodyWordsToTokensRatioBegin)
	s.BodyWordsToTokensRatioTotal = float64(s1.BodyWordsToTokensRatioTotal)
	s.CommercialScore = float64(s1.CommercialScore)
	s.Pagerank = float64(s1.Pagerank)
	s.Pagerank0 = float64(s1.Pagerank0)
	s.Pagerank1 = float64(s1.Pagerank1)
	s.Pagerank2 = float64(s1.Pagerank2)
	s.SpambrainTotalDocSpamScore = float64(s1.SpambrainTotalDocSpamScore)
	s.SpamtokensContentScore = float64(s1.SpamtokensContentScore)
	s.TopPetacatWeight = float64(s1.TopPetacatWeight)
	return nil
}

